// Builds Azahar's Android front end and native core as an Android library (AAR)
// that the Blossom app embeds. Settings mirror Azahar's src/android/app/build.gradle.kts.
// Sources under src/main are generated by ../../prepare.py and are not committed.

plugins {
    id("com.android.library")
    id("org.jetbrains.kotlin.android")
    id("kotlin-parcelize")
    id("org.jetbrains.kotlin.plugin.serialization")
    id("androidx.navigation.safeargs.kotlin")
}

val azaharDir = file("../../azahar")
val azaharCommit = file("../../AZAHAR_COMMIT").readText().trim()
val azaharShort = azaharCommit.take(9)

android {
    namespace = "org.citra.citra_emu"

    compileSdkVersion = "android-37"
    ndkVersion = "27.3.13750724"

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    kotlinOptions {
        jvmTarget = "17"
    }

    buildFeatures {
        viewBinding = true
        buildConfig = true
    }

    lint {
        abortOnError = false
        checkReleaseBuilds = false
    }

    defaultConfig {
        minSdk = 29

        ndk {
            abiFilters += listOf("arm64-v8a")
        }

        externalNativeBuild {
            cmake {
                arguments(
                    "-DENABLE_QT=0",
                    "-DENABLE_SDL2=0",
                    "-DANDROID_ARM_NEON=true",
                    "-DANDROID_SUPPORT_FLEXIBLE_PAGE_SIZES=ON",
                    "-DENABLE_GDBSTUB=OFF"
                )
            }
        }

        // Library modules do not get VERSION_NAME for free.
        buildConfigField("String", "VERSION_NAME", "\"blossom-$azaharShort\"")
        buildConfigField("String", "GIT_VERSION", "\"blossom-$azaharShort\"")
        buildConfigField("String", "GIT_HASH", "\"$azaharShort\"")
        buildConfigField("String", "BRANCH", "\"blossom\"")

        consumerProguardFiles("consumer-rules.pro")
    }

    buildTypes {
        release {
            // Shrinking happens once, in the Blossom app.
            isMinifyEnabled = false
        }
    }

    flavorDimensions.add("version")
    productFlavors {
        register("vanilla") {
            dimension = "version"
        }
    }

    externalNativeBuild {
        cmake {
            version = "3.25.0+"
            path = file("$azaharDir/CMakeLists.txt")
        }
    }
}

dependencies {
    implementation("androidx.activity:activity-ktx:1.9.2")
    implementation("androidx.appcompat:appcompat:1.7.0")
    implementation("androidx.core:core-splashscreen:1.0.1")
    implementation("androidx.documentfile:documentfile:1.0.1")
    implementation("androidx.fragment:fragment-ktx:1.8.3")
    implementation("androidx.lifecycle:lifecycle-viewmodel-ktx:2.8.5")
    implementation("androidx.navigation:navigation-fragment-ktx:2.8.0")
    implementation("androidx.navigation:navigation-ui-ktx:2.8.0")
    implementation("androidx.preference:preference-ktx:1.2.1")
    implementation("androidx.recyclerview:recyclerview:1.3.2")
    implementation("androidx.slidingpanelayout:slidingpanelayout:1.2.0")
    implementation("androidx.swiperefreshlayout:swiperefreshlayout:1.1.0")
    implementation("androidx.work:work-runtime:2.9.1")
    implementation("com.google.android.material:material:1.9.0")
    implementation("info.debatty:java-string-similarity:2.0.0")
    implementation("io.coil-kt:coil:2.7.0")
    implementation("org.ini4j:ini4j:0.5.4")
    implementation("org.jetbrains.kotlinx:kotlinx-serialization-json:1.7.2")
}

// The library-only resource verification step cannot resolve navigation graphs that
// layouts reference (@navigation/...). The Blossom app links all resources for real
// when it embeds this AAR, so nothing is lost by skipping the extra check here.
tasks.matching { it.name.startsWith("verify") && it.name.endsWith("Resources") }.configureEach {
    enabled = false
}
